                NeuronGenerationInitialReadbackV1::Published(published) => Ok(published),
                NeuronGenerationInitialReadbackV1::Prepared => {
                    Err(invalid("initial generation publication remains uncertain"))
                }
            }
        },
    )
    .map_err(invalid)?;
    result
}

